<script setup lang="ts">
import {ref,watch} from 'vue'
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,hosts:Record<string,any>[],editing?:Record<string,any>|null} >(),emit=defineEmits(['saved'])
const host=ref(''),name=ref(''),ssh=ref(22),admins=ref(''),rules=ref<Record<string,any>[]>([]),busy=ref(false),error=ref('')
watch(()=>props.editing,v=>{if(v){host.value=v.host_id;name.value=v.policy.name;ssh.value=v.policy.ssh_port;admins.value=v.policy.admin_cidrs.join('\n');rules.value=JSON.parse(JSON.stringify(v.policy.rules))}else{host.value='';name.value='';ssh.value=22;admins.value='';rules.value=[]}})
async function save(){busy.value=true;error.value='';try{const policy={name:name.value,ssh_port:ssh.value,admin_cidrs:admins.value.split(/[\s,]+/).filter(Boolean),default_action:'drop',rules:rules.value};if(props.editing)await props.api('firewalls/'+props.editing.id,'PUT',{version:props.editing.version,policy});else await props.api('hosts/'+host.value+'/firewalls','POST',policy);emit('saved')}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><details :open="!!editing"><summary>新建 / 修改策略版本</summary><form @submit.prevent="save"><div class="fields"><label>主机<select v-model="host" :disabled="!!editing" required><option value="">选择 VPS</option><option v-for="h in hosts" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>策略名称<input v-model="name" required maxlength="100"></label><label>SSH 端口<input v-model.number="ssh" type="number" min="1" max="65535" required></label><label>允许管理的 IPv4 / IPv6 CIDR<input v-model="admins" required placeholder="例如 192.0.2.1/32，2001:db8::1/128"></label></div><div v-for="(r,i) in rules" :key="i" class="firewall-rule"><label>规则名<input v-model="r.name" required></label><label>协议<select v-model="r.protocol"><option>tcp</option><option>udp</option></select></label><label>业务端口<input v-model.number="r.port" type="number" min="1" max="65535" required></label><label>来源 CIDR<input v-model="r.source" required></label><button type="button" class="text-button danger" @click="rules.splice(i,1)">移除</button></div><button type="button" class="secondary" @click="rules.push({name:'代理入口',protocol:'tcp',port:2080,source:'0.0.0.0/0',action:'accept'})">添加放行规则</button><p class="muted">IPv4 与 IPv6 分别添加规则；HY2 / TUIC 使用 UDP。旧策略和审计保留，新建版本不会自动应用。</p><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="busy">{{editing?'保存为新版本':'保存待验证策略'}}</button><button v-if="editing" class="secondary" type="button" @click="emit('saved')">取消编辑</button></form></details></template>
